function uploadCertificate(array $u):array{if(!in_array($u['role'],['employee','commission']))throw new Fault('O envio deve ser realizado pelo servidor.',403);$p=linkFor($u,$_GET['linkId']??'',true);$eligible=[];foreach(records($u['tenant'],'appointments') as $a){if(!$a['active']||$a['plan']!==$p['planId']||$a['unit']!==$p['unitId']||$a['start']>today()||$a['end']<today()||($a['lotation']??'')&&$a['lotation']!==$p['lotation'])continue;$ok=true;foreach($a['members'] as $m)if($m['personId']===$p['personId']||$m['admission']>=$p['admission'])$ok=false;if($ok)$eligible[]=$a;}if(count($eligible)!==1)throw new Fault('Não há uma única comissão vigente e elegível para esta matrícula. Solicite ajuste da designação.');$a=$eligible[0];$bytes=file_get_contents('php://input',false,null,0,10485761);if(strlen($bytes)>10485760||!str_starts_with($bytes,'%PDF-')||stripos($bytes,'%%EOF')===false||($_SERVER['CONTENT_TYPE']??'')!=='application/pdf')throw new Fault('Envie um PDF válido de até 10 MB.');$hash=hash('sha256',$bytes);foreach(records($u['tenant'],'certificates') as $c)if($c['link']===$p['id']&&$c['hash']===$hash)throw new Fault('PDF já enviado nesta matrícula.',409);$completed=day($_GET['completed']??'');if($completed>today()||$completed<$p['admission'])throw new Fault('Conclusão fora do período da matrícula.');$plan=record($u['tenant'],'plans',$p['planId']);$categoryId=$_GET['categoryId']??'';$accepted=null;foreach($plan['certificateCategories']??[] as $c)if($c['id']===$categoryId)$accepted=$c;if(!$accepted||$accepted['destination']!==($_GET['destination']??''))throw new Fault('Categoria ou destino não cadastrado no plano desta matrícula.');$category=$accepted['label'];$destination=$accepted['destination'];$kind=$accepted['kind'];$hours=num($_GET['hours']??0,0,10000,'horas');if($hours<$accepted['minHours'])throw new Fault('O certificado não atinge a carga horária mínima da categoria.');$target=trim($_GET['targetLevel']??'');if($kind==='Titulação'&&!$target)throw new Fault('Informe o nível pretendido.');$id=uid();$name=basename(need($_GET['fileName']??'certificado.pdf','nome do PDF',160));if(!str_ends_with(strtolower($name),'.pdf'))throw new Fault('Extensão inválida.');file_put_contents(TR_PRIVATE.'/data/'.$id.'.enc',seal($bytes),LOCK_EX);@chmod(TR_PRIVATE.'/data/'.$id.'.enc',0600);try{query('INSERT INTO tr_files(id,tenant,link_id,name,size,hash,created) VALUES(?,?,?,?,?,?,?)',[$id,$u['tenant'],$p['id'],$name,strlen($bytes),$hash,date(DATE_ATOM)]);$c=save($u['tenant'],'certificates',['id'=>$id,'link'=>$p['id'],'employee'=>$p['name'],'registration'=>$p['registration'],'plan'=>$p['planId'],'appointment'=>$a['id'],'name'=>need($_GET['name']??'','curso',180),'category'=>$category,'categoryId'=>$categoryId,'destination'=>$destination,'kind'=>$kind,'targetLevel'=>$target,'hours'=>$hours,'completed'=>$completed,'reviewers'=>$a['members'],'votes'=>[],'hash'=>$hash,'fileName'=>$name,'size'=>strlen($bytes),'submittedBy'=>$u['id'],'created'=>date(DATE_ATOM),'createdDay'=>today()]);audit($u['tenant'],'certificate.submit',$id);return ['id'=>$c['id']];}catch(Throwable $e){@unlink(TR_PRIVATE.'/data/'.$id.'.enc');throw $e;}}
function serveCertificate(array $u,string $id):never{$c=record($u['tenant'],'certificates',$id);$p=$c?record($u['tenant'],'links',$c['link']):null;$a=$c?record($u['tenant'],'appointments',$c['appointment']):null;$admin=$u['role']==='admin'&&!$u['unit']&&!$u['power'];if(!$c||!$p||!($admin||$p['personId']===$u['person']||$a&&reviewerAllowed($u,$a,$p)))throw new Fault('Documento não encontrado neste acesso.',404);$file=TR_PRIVATE.'/data/'.$id.'.enc';if(!is_file($file))throw new Fault('Documento indisponível.',404);$ticket=save($u['tenant'],'reads',['id'=>uid(),'certificate'=>$id,'member'=>$u['id'],'at'=>time()]);audit($u['tenant'],'certificate.view',$id);$bytes=unseal((string)file_get_contents($file));header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="certificado.pdf"');header('X-Document-Read: '.$ticket['id']);header("Content-Security-Policy: sandbox; default-src 'none'");echo $bytes;exit;}
